-- Automechaniker + Schreiner: Bildungsplan-Fragenkatalog (16 × 30 Fragen).
-- Idempotent, additiv und ohne Datenverlust:
--   * course_key-CHECK-Constraints werden auf abu/automechaniker/schreiner/strassenbau erweitert.
--   * Module werden nach (course_key, title) gesucht oder angelegt.
--   * Lektionen werden nach (module_id, title) gesucht oder angelegt;
--     position/pass_score werden gesetzt.
--   * Fragen werden positionsbasiert UPSERTet: vorhandene (lesson_id,
--     position) werden aktualisiert (question.id bleibt erhalten, FKs zu
--     question_xp_awards / battle_answers bleiben intakt). Fehlende
--     Positionen werden eingefügt. Positionen > 30 werden entfernt.
--   * Profile, lesson_progress, lesson_attempts werden nicht angetastet.

begin;

-- ============================================================
-- 1) course_key-CHECK-Constraints erweitern
-- ============================================================
do $$
begin
  if exists (select 1 from pg_constraint where conname = 'profiles_active_course_key_ck') then
    alter table public.profiles drop constraint profiles_active_course_key_ck;
  end if;
  alter table public.profiles
    add constraint profiles_active_course_key_ck check (active_course_key in ('abu', 'automechaniker', 'schreiner', 'strassenbau'));
end$$;

do $$
begin
  if exists (select 1 from pg_constraint where conname = 'modules_course_key_ck') then
    alter table public.modules drop constraint modules_course_key_ck;
  end if;
  alter table public.modules
    add constraint modules_course_key_ck check (course_key in ('abu', 'automechaniker', 'schreiner', 'strassenbau'));
end$$;

do $$
begin
  if to_regclass('public.battle_matches') is not null then
    if exists (select 1 from pg_constraint where conname = 'battle_matches_course_key_ck') then
      alter table public.battle_matches drop constraint battle_matches_course_key_ck;
    end if;
    alter table public.battle_matches
      add constraint battle_matches_course_key_ck check (course_key in ('abu', 'automechaniker', 'schreiner', 'strassenbau'));
  end if;
end$$;

-- ============================================================
-- 2) AUTOMECHANIKER: 1 Modul, 16 Lektionen je 30 Fragen
-- ============================================================
do $$
declare
  v_module_id uuid;
  v_lesson_id uuid;
begin
  select id into v_module_id from public.modules where course_key = 'automechaniker' and title = 'Automechaniker/in EFZ – Bildungsplan' limit 1;
  if v_module_id is null then
    insert into public.modules (title, description, course_key, position)
    values ('Automechaniker/in EFZ – Bildungsplan', 'Bildungsplan Automechaniker/in EFZ. 16 Lektionen entlang der Handlungskompetenzbereiche HKB1–HKB5 mit Fokus auf Inspektion, Service, Antriebsstrang, Elektrik/Elektronik, Komfort- und Sicherheitssysteme sowie alternative Antriebe.', 'automechaniker', 100)
    returning id into v_module_id;
  else
    update public.modules set description = 'Bildungsplan Automechaniker/in EFZ. 16 Lektionen entlang der Handlungskompetenzbereiche HKB1–HKB5 mit Fokus auf Inspektion, Service, Antriebsstrang, Elektrik/Elektronik, Komfort- und Sicherheitssysteme sowie alternative Antriebe.', position = 100 where id = v_module_id;
  end if;

  -- Lektion L01: L01 – Werkstatt-Basics, Auftrag und Ersatzteile
  select id into v_lesson_id from public.lessons where module_id = v_module_id and title = 'L01 – Werkstatt-Basics, Auftrag und Ersatzteile' limit 1;
  if v_lesson_id is null then
    insert into public.lessons (module_id, title, position, pass_score)
    values (v_module_id, 'L01 – Werkstatt-Basics, Auftrag und Ersatzteile', 10, 70)
    returning id into v_lesson_id;
  else
    update public.lessons set position = 10, pass_score = 70 where id = v_lesson_id;
  end if;
  update public.questions set prompt = 'Welche Aussage beschreibt das Thema Werkstattauftrag im Beruf Automobil-Mechatroniker/in EFZ am besten?', option_a = 'er beschreibt Kundenbeanstandung, auszuführende Arbeiten und wichtige Fahrzeugdaten', option_b = 'er ersetzt die Abschlusskontrolle im laufenden Tagesgeschäft bei sachgemässem Ablauf', option_c = 'er enthält nur den Verkaufspreis im konkreten Auftrag im Produktionsalltag', option_d = 'er wird erst nach der Probefahrt erstellt im Werkstattumfeld', correct_option = 'A', explanation = 'Ein klarer Auftrag ist Grundlage für fachgerechte, nachvollziehbare Arbeiten.' where lesson_id = v_lesson_id and position = 1;
  if not found then insert into public.questions (lesson_id, prompt, option_a, option_b, option_c, option_d, correct_option, explanation, position) values (v_lesson_id, 'Welche Aussage beschreibt das Thema Werkstattauftrag im Beruf Automobil-Mechatroniker/in EFZ am besten?', 'er beschreibt Kundenbeanstandung, auszuführende Arbeiten und wichtige Fahrzeugdaten', 'er ersetzt die Abschlusskontrolle im laufenden Tagesgeschäft bei sachgemässem Ablauf', 'er enthält nur den Verkaufspreis im konkreten Auftrag im Produktionsalltag', 'er wird erst nach der Probefahrt erstellt im Werkstattumfeld', 'A', 'Ein klarer Auftrag ist Grundlage für fachgerechte, nachvollziehbare Arbeiten.', 1); end if;
  update public.questions set prompt = 'Worauf muss man beim Thema Werkstattauftrag in der Werkstatt besonders achten?', option_a = 'er ersetzt die Abschlusskontrolle nach gängiger Praxis im Rahmen der Routine', option_b = 'er beschreibt Kundenbeanstandung, auszuführende Arbeiten und wichtige Fahrzeugdaten', option_c = 'er enthält nur den Verkaufspreis im üblichen Berufsalltag bei vergleichbaren Aufgaben', option_d = 'er wird erst nach der Probefahrt erstellt unter typischen Arbeitsbedingungen', correct_option = 'B', explanation = 'Ein klarer Auftrag ist Grundlage für fachgerechte, nachvollziehbare Arbeiten.' where lesson_id = v_lesson_id and position = 2;
  if not found then insert into public.questions (lesson_id, prompt, option_a, option_b, option_c, option_d, correct_option, explanation, position) values (v_lesson_id, 'Worauf muss man beim Thema Werkstattauftrag in der Werkstatt besonders achten?', 'er ersetzt die Abschlusskontrolle nach gängiger Praxis im Rahmen der Routine', 'er beschreibt Kundenbeanstandung, auszuführende Arbeiten und wichtige Fahrzeugdaten', 'er enthält nur den Verkaufspreis im üblichen Berufsalltag bei vergleichbaren Aufgaben', 'er wird erst nach der Probefahrt erstellt unter typischen Arbeitsbedingungen', 'B', 'Ein klarer Auftrag ist Grundlage für fachgerechte, nachvollziehbare Arbeiten.', 2); end if;
